  const q = (s) => C() && C().querySelector(s); const qa = (s) => C() ? [...C().querySelectorAll(s)] : [];
  const ep = () => mg().getTestState().episode; const g = () => W.gameState.globalVariables; const ST = () => g().episode_e1_stub_state;
  const since = (m) => { const l = t.peekLog(800); let i = -1; l.forEach((e, j) => { if (e.kind === 'note' && e.message === m) i = j; }); return l.slice(i + 1).filter(e => e.kind === 'event'); };
  const noFail = (m) => !since(m).some(e => e.event === 'minigame_failed' && e.data && e.data.minigameName === 'EpisodeRunnerMinigame');
